/**
 * Bundled BSB content access. Single-translation build (owner decision):
 * every surface reads version identity from `activeTranslation`, never from
 * hardcoded strings, so a future second translation only extends this file.
 *
 * Assets are generated by `tools/build-bsb-assets.py` from the local `bsb/`
 * dataset (never committed). Metro bundles the per-book files; they parse on
 * first chapter open — the SQLite content cache (Phase 8) replaces this.
 */

import { bookByOsis } from './books';

// Metro provides require() at runtime for bundled JSON assets.
declare const require: (path: string) => unknown;

export interface TranslationRecord {
  id: string;
  name: string;
  short: string;
  attribution: string;
  licenseUrl: string;
  rightsBasis: string;
}

export const activeTranslation: TranslationRecord = {
  id: 'BSB',
  name: 'Berean Standard Bible',
  short: 'BSB',
  attribution: 'Berean Standard Bible · BSB',
  licenseUrl: 'https://berean.bible/',
  rightsBasis: 'Owner-confirmed berean.bible distribution terms; formal sign-off pending (CONTENT_RIGHTS.md).',
};

export type ChapterBlock =
  | { kind: 'heading'; text: string }
  | { kind: 'verse'; number: number; text: string };

export interface ChapterContent {
  bookOsis: string;
  bookName: string;
  chapter: number;
  blocks: ChapterBlock[];
  verseCount: number;
}

interface BookAsset {
  osis: string;
  name: string;
  chapters: Array<{ n: number; blocks: Array<{ t: string; n?: number; text: string }> }>;
}

