/** Whole-chapter content. Returns null for unknown books or chapters. */
export function getChapter(bookOsis: string, chapter: number): ChapterContent | null {
  const entry = bookByOsis(bookOsis);
  const load = BOOK_ASSETS[bookOsis];
  if (!entry || !load || chapter < 1 || chapter > entry.chapters) return null;
  const asset = load() as BookAsset;
  const found = asset.chapters.find((item) => item.n === chapter);
  if (!found) return null;
  const blocks: ChapterBlock[] = found.blocks.map((block) =>
    block.t === 'h'
      ? { kind: 'heading', text: block.text }
      : { kind: 'verse', number: block.n ?? 0, text: block.text },
  );
  return {
    bookOsis,
    bookName: entry.name,
    chapter,
    blocks,
    verseCount: blocks.filter((block) => block.kind === 'verse').length,
  };
}

/** Plain verse text, e.g. the daily verse. Null when absent. */
export function getVerseText(bookOsis: string, chapter: number, verse: number): string | null {
  const content = getChapter(bookOsis, chapter);
  if (!content) return null;
  const block = content.blocks.find(
    (item): item is { kind: 'verse'; number: number; text: string } =>
      item.kind === 'verse' && item.number === verse,
  );
  return block ? block.text : null;
}
